[samples/frostAxe.ts#8CE1]
1:// Frost-forged battle axe on a rune plinth: League of Legends style (saturated cyan magic against deep navy steel,
2:// gold trim, crimson accents, big exaggerated crescent blade, glowing frost runes).
3:import * as THREE from "three";
4:import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
5:import { createBuilder } from "../src/builder";
6:import type { OutlinePoint } from "../src/builder";
7:import { aim, rng } from "../src/math";
8:import { catmull, spiral } from "../src/path";
9:import { cells, noise, paint, scales } from "../src/paint";
10:import { svg } from "../src/texture";
11:import { glow } from "../kits/glow";
12:import { cel, zigzag } from "../kits/toon";
13:
14:export const meta = {
15:  name: "Frost-Forged Battle Axe",
16:  description:
17:    "A towering two-handed frost axe on a rune-carved plinth: crescent main blade with glowing frost-fern runes, ice-fang counter blade, gold langets and rivets, crimson pennants, hanging frost charm.",
18:  style: "League of Legends",
19:  commit: "88fc1f0",
20:};
21:
22:// Palette
23:const STEEL = "#9cc4ee";
24:const FROST = "#eafaff";
25:const ICE = "#8fe6ff";
26:const ICE2 = "#c9f4ff";
27:const ICE3 = "#3fb0f0";
28:const GLOW = "#4df0ff";
29:const GLOWCORE = "#d8ffff";
30:const GOLD = "#f0bf4e";
31:const GOLD2 = "#b8702a";
32:const CRIMSON = "#e0305e";
33:const CRIMSON2 = "#8f1d49";
34:const SNOW = "#f4fbff";
35:
36:type UV = [number, number] | [number, number, "sharp"];
37:type Pt = [number, number];
